/*
 * A183169  Tree generated by the squares.
 * https://oeis.org/A183169
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) is the n‑th element of the breadth‑first traversal of a
 *            binary tree in which each node v has left child v^2 and right
 *            child the v‑th non‑square number (A000037). The tree starts with
 *            root 1 (row 0) and row 1 contains a single element 2. For n≥2,
 *            rows have 2^(n‑1) elements. The sequence a(n)...
 * Range:     u8 n <= 7, u16 n <= 16, u32 n <= 32, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/floor_sqrt.h"

/* Return the idx‑th non‑square number (1‑based).  */
static seq_t nth_non_square(seq_t idx)
{
    seq_t low  = (seq_t)1;
    /* Ensure the upper bound is ≥ answer.  */
    seq_t high = idx + floor_sqrt(idx) + (seq_t)1024;

    while (low < high)
    {
        seq_t mid = (low + high) >> 1;
        seq_t sq  = floor_sqrt(mid);
        seq_t count = mid - sq;              /* number of non‑squares ≤ mid */

        if (count >= (seq_t)idx)
            high = mid;
        else
            low = mid + (seq_t)1;
    }
    return low;
}

seq_t a(idx_t n)
{
    if (n == 1ULL) return (seq_t)1;
    if (n == 2ULL) return (seq_t)2;

    /* Cumulative number of elements processed so far.  */
    idx_t cum = 2;          /* 1 (root) + 1 (row 1) already counted */

    /* Prepare row 1 as the previous row for generating row 2.  */
    size_t prevSize = 1;
    seq_t *prev = (seq_t*)calloc(prevSize, sizeof(seq_t));
    prev[0] = (seq_t)2;

    /* Generate rows sequentially until we reach the row containing n.  */
    while (true)
    {
        size_t nextSize = prevSize * 2;
        seq_t *next = (seq_t*)malloc(nextSize * sizeof(seq_t));

        for (size_t i = 0; i < prevSize; ++i)
        {
            seq_t parent = prev[i];
            next[2 * i]     = parent * parent;
            next[2 * i + 1] = nth_non_square(parent);
        }

        cum += nextSize;
        if (n <= cum)
        {
            idx_t prevCum   = cum - nextSize;
            idx_t offset    = n - prevCum - 1;
            seq_t result    = next[offset];
            /* Free allocated memory before returning. */
            free(prev);
            free(next);
            return result;
        }

        free(prev);
        prev      = next;
        prevSize  = nextSize;
    }
}
